P=Path(__file__).parent;R=P/'results';load=lambda f:json.loads((R/f).read_text());C=load('corpus.json');counts=load('word_counts.json');H=load('hypotheses.json');W={x['word']:x for x in H if x['hypothesis']=='A_world' and x['n']};matched=load('matched_hypotheses.json');groups=load('groups.json');cases=load('case_index.json');anti=load('antipodality.json');contra=load('same_pair_opposite_descriptions.json')
