axis={0.:'+X',90.:'+Y',180.:'−X',270.:'−Y'}
lines=[]
def add(s=''):lines.append(s)
def table(headers,rows):
 add('| '+' | '.join(headers)+' |');add('| '+' | '.join(['---']*len(headers))+' |')
 for row in rows:add('| '+' | '.join(str(x) for x in row)+' |')
 add()
add('# CityNav TRAIN 空间方向词参考系独立实验')
add('\n日期：2026-11-06。分支：`experiment/citynav-direction-frames-20261106`。版本：direction-frames v1。')
add('\n## 结论与适用范围\n')
add(f'**不能把 CityNav 中的 left/right 或 front/behind 作为统一、确定的世界坐标方向约束。** 完整扫描原始 TRAIN 的 {C["episodes"]:,} 条 episode，在 {C["maps"]} 张地图发现 {C["direction_occurrences"]:,} 次指定方向词出现。严格绑定并排除轮廓相交/近边界后保留 {C["valid_direct_pairs"]} 对（{C["valid_clusters"]} 个目标对象）。在这一保守子集中，四个主要方向词即使分别选择最有利的世界坐标轴，其 90° 扇区一致率也只有 33–44%。更强的反例是：同一真实目标、同一参照物、同一 ΔXY，出现了 {len(contra)} 组正反词描述。')
add('\n这足以否定“全部指令遵守统一固定轴约定”的强命题；**不能**据此估计整个数据集里不同描述参考系的真实混合比例。保守解析的覆盖率低，所选样本偏向具名地标与简单句式，其他指令仍不可外推。统计上更集中也不等于已经证明描述者采用该参考系。')
add('\n## 数据来源与隔离\n')
add('- 仅打开 `original_citynav/citynav_train_seen.json`：22,002 条；没有读取 Val/Test，也未用其校准方向。\n- 使用 `cityrefer_original/objects.json` 与 `processed_descriptions.json`；后者只记录来源，不用其无作用域的 landmarks 列表建立关系。原始对象库有 34 张地图，本分析仅使用 TRAIN 出现的 24 张地图。\n- GT 仅在文本解析和唯一名称解析完成后进入离线几何层；没有模型推理、训练或权重加载。Geometry、Relation、PGVB 网络均未改动。\n- 原始输入 SHA256、参数和软件版本见 [manifest.json](results/manifest.json)。全部 TRAIN episode 及目标 GT 见 [episodes_train.csv](results/episodes_train.csv)，目标轮廓见 [target_catalog_train.json](results/target_catalog_train.json)，全部 TRAIN 地图具名对象（含同名候选）轮廓见 [reference_catalog_train.json](results/reference_catalog_train.json)；底图和 TIF SHA256 见 [raster_manifest.json](results/raster_manifest.json)。')
add(f'\nTRAIN 指令与 CityRefer 的同一 `ann_id` 原文比较发现 {C["description_mismatches"]} 条不完全一致，详见 [annotation_alignment_audit.json](results/annotation_alignment_audit.json)。本实验将相应候选关系排除，未依据相似文本或 GT 强行重配。重复英文保留为不同原始 annotation，但另有唯一英文、唯一配对加权敏感性统计。')
add('\n## 提取协议与数量\n')
add('主统计用大小写不敏感的完整单词边界，逐次记录 left/right/front/behind/back/rear/above/below/top/bottom/north/south/east/west。另扫描 leftmost/rightmost、复合地理词、upper/lower/backyard 等，见 [extended_lexemes.json](results/extended_lexemes.json)，不混入单词统计。词次数、指令数、唯一英文数不能混用。')
add('\n严格可接受关系要求：目标为主句/明确前置关系的主语，关系后紧接同地图唯一完整具名对象；允许标点与冠词正规化，不作模糊别名匹配；多个同名对象不选最近对象。匿名车/树、介词链、子区域、多个参照物协调、未定指代均不猜测。`car in a parking lot behind Church` 不转成 car behind Church；`behind the yard of Church` 不把 Church 当直接参照物。`right next to`、`West Midlands`、`front yard`、`rear bumper`、序数/局部位置和对角复合方向分别记录排除。')
add('\n“绑定数”包括被轮廓检验排除的样本；“有效数”仅表示可做位移角分析，不表示某种方向假设正确。对每个参考系还另做完整轮廓的方向显著性判定。')
table(['词','出现次数','含词 episode','唯一英文','绑定数','有效数','排除或 ambiguous'],[[c[k] for k in ['word','occurrences','episodes','unique_instruction_texts','bound_pairs','valid','excluded_or_ambiguous']] for c in counts])
add(f'几何/绑定无法进入主角度分析：{C["direction_occurrences"]-C["valid_direct_pairs"]:,}/{C["direction_occurrences"]:,} = **{pct(C["unresolved_geometry_or_binding_fraction"])}**。这包含非关系词与保守解析漏检，不能称为“99% 指令使用了未知参考系”。全部 {C["episodes_with_direction"]:,} 条含方向词 episode 中，{C["valid_direction_episodes"]} 条有有效配对（{pct(C["valid_direction_episodes"]/C["episodes_with_direction"])}）。')
add('\n逐词、逐原因、逐作用域的全部计数见 [exclusion_reasons.csv](results/exclusion_reasons.csv)；每次出现的原文、字符偏移、目标 ID、候选参照 ID、规则和状态见 [occurrences.csv](results/occurrences.csv) / [occurrences.json](results/occurrences.json)。有效集已做助手英文作用域审读，记录于 [accepted_scope_audit.csv](results/accepted_scope_audit.csv)；它不是人工标注金标准，也不是独立审稿。')
